pub const CLAP_ERRORS_401: &str = "/usr/local/cargo/registry/src/index.crates.io-6f17d22bba15001f/clap-2.33.0/src/errors.rs:401:55";

pub fn panic_fake(location: &str, message: &str) -> ! {
