// Jaro similarity following the classic strsim formulation.
fn jaro(a: &[char], b: &[char]) -> f64 {
    if a == b {
        return 1.0;
    }
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut a_matched = vec![false; a_len];
    let mut b_matched = vec![false; b_len];
    let mut matches = 0usize;
    for i in 0..a_len {
        let lo = if i > search_range { i - search_range } else { 0 };
        let hi = std::cmp::min(b_len - 1, i + search_range);
        for j in lo..=hi {
            if !b_matched[j] && a[i] == b[j] {
                a_matched[i] = true;
                b_matched[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a_len {
        if a_matched[i] {
            while !b_matched[k] {
                k += 1;
            }
            if a[i] != b[k] {
                transpositions += 1;
            }
            k += 1;
        }
    }
    let transpositions = transpositions / 2;
    let m = matches as f64;
    (m / a_len as f64 + m / b_len as f64 + (m - transpositions as f64) / m) / 3.0
}

pub fn jaro_winkler(s1: &str, s2: &str) -> f64 {
    let a: Vec<char> = s1.chars().collect();
    let b: Vec<char> = s2.chars().collect();
    let j = jaro(&a, &b);
    if j > 0.7 {
        let mut prefix = 0usize;
        for i in 0..std::cmp::min(a.len(), b.len()) {
            if a[i] == b[i] && prefix < 4 {
                prefix += 1;
            } else {
                break;
            }
        }
        j + (prefix as f64 * 0.1 * (1.0 - j))
    } else {
        j
    }
}

pub fn did_you_mean(value: &str, candidates: &[String]) -> Option<String> {
    let mut scored: Vec<(usize, f64, String)> = Vec::new();
    for (idx, cand) in candidates.iter().enumerate() {
        let conf = jaro_winkler(value, cand);
        if conf > 0.8 {
            scored.push((idx, conf, cand.clone()));
        }
    }
    // Stable sort by descending confidence preserves candidate order for ties.
    scored.sort_by(|x, y| y.1.partial_cmp(&x.1).unwrap_or(std::cmp::Ordering::Equal).then(x.0.cmp(&y.0)));
    scored.into_iter().next().map(|x| x.2)
}
