use crate::help;
use crate::util::*;
use std::collections::{HashMap, HashSet};
use std::io::{self, Write};

pub type Bytes = Vec<u8>;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ArgKind { Flag, OptSingle, OptMulti, PosSingle, PosMulti }

#[derive(Clone, Debug)]
pub struct ArgDef {
    pub id: &'static str,
    pub long: Option<&'static str>,
    pub short: Option<char>,
    pub kind: ArgKind,
    pub display: &'static str, // for flags/options errors & smart usage; for pos it's "<alias>" etc.
    pub required: bool,
}

#[derive(Clone, Debug)]
pub struct AppSpec {
    pub canonical: Option<&'static str>, // None top
    pub defs: Vec<ArgDef>,
}

impl AppSpec {
    pub fn bin_prefix(&self, bin: &str) -> String {
        match self.canonical {
            None => bin.to_string(),
            Some(c) => format!("{} {}", bin, c),
        }
    }
    pub fn full_usage(&self, bin: &str) -> String {
        let b = bin;
        let lines: Vec<String> = match self.canonical {
            None => vec![
                format!("{} [FLAGS] [OPTIONS] <alias> [args]...", b),
                format!("{} [FLAGS] [OPTIONS] <SUBCOMMAND>", b),
            ],
            Some("add") => vec![format!("{} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]", b)],
            Some("config-init") => vec![format!("{} config-init", b)],
            Some("copy") => vec![format!("{} copy <from-alias> <to-alias>", b)],
            Some("edit") => vec![format!("{} edit <alias>", b)],
            Some("list") => vec![format!("{} list [FLAGS] [OPTIONS]", b)],
            Some("move") => vec![format!("{} move [FLAGS] <from-alias> <to-alias>", b)],
            Some("remove") => vec![format!("{} remove <alias>", b)],
            Some("run") => vec![format!("{} run <alias> [args]...", b)],
            Some("show") => vec![format!("{} show <alias>", b)],
            _ => vec![b.to_string()],
        };
        lines.iter().map(|l| format!("    {}", l)).collect::<Vec<_>>().join("\n")
    }
    pub fn def_by_id(&self, id: &str) -> Option<&ArgDef> { self.defs.iter().find(|d| d.id == id) }
}

pub fn help_version_defs() -> Vec<ArgDef> {
    vec![
        ArgDef{id:"help", long:Some("help"), short:Some('h'), kind:ArgKind::Flag, display:"--help", required:false},
        ArgDef{id:"version", long:Some("version"), short:Some('V'), kind:ArgKind::Flag, display:"--version", required:false},
    ]
}

pub fn top_spec() -> AppSpec {
    let mut defs = help_version_defs();
    defs.extend(vec![
        ArgDef{id:"verbose", long:Some("verbose"), short:Some('v'), kind:ArgKind::Flag, display:"--verbose", required:false},
        ArgDef{id:"config-file", long:Some("config-file"), short:Some('c'), kind:ArgKind::OptSingle, display:"--config-file <path>", required:false},
        ArgDef{id:"alias", long:None, short:None, kind:ArgKind::PosSingle, display:"<alias>", required:true},
        ArgDef{id:"args", long:None, short:None, kind:ArgKind::PosMulti, display:"[args]...", required:false},
    ]);
    AppSpec{canonical:None, defs}
}

pub fn spec_for(sub: &str) -> AppSpec {
    let mut defs = help_version_defs();
    match sub {
        "add" => defs.extend(vec![
            ArgDef{id:"force", long:Some("force"), short:Some('f'), kind:ArgKind::Flag, display:"--force", required:false},
            ArgDef{id:"alias", long:Some("alias"), short:Some('a'), kind:ArgKind::OptSingle, display:"--alias <alias>", required:true},
            ArgDef{id:"description", long:Some("description"), short:Some('d'), kind:ArgKind::OptSingle, display:"--description <description>", required:false},
            ArgDef{id:"tags", long:Some("tag"), short:Some('t'), kind:ArgKind::OptMulti, display:"--tag <tags>...", required:false},
