        ]),
        "list" => defs.extend(vec![
            ArgDef{id:"cmd_full", long:Some("cmd_full"), short:Some('l'), kind:ArgKind::Flag, display:"--cmd_full", required:false},
            ArgDef{id:"list_aliases", long:Some("list_aliases"), short:Some('q'), kind:ArgKind::Flag, display:"--list_aliases", required:false},
            ArgDef{id:"cmd_width", long:Some("cmd_width"), short:Some('c'), kind:ArgKind::OptSingle, display:"--cmd_width <cmd-width>", required:false},
            ArgDef{id:"tags", long:Some("tag"), short:Some('t'), kind:ArgKind::OptMulti, display:"--tag <tags>...", required:false},
        ]),
        "move" => defs.extend(vec![
            ArgDef{id:"force", long:Some("force"), short:Some('f'), kind:ArgKind::Flag, display:"--force", required:false},
            ArgDef{id:"from-alias", long:None, short:None, kind:ArgKind::PosSingle, display:"<from-alias>", required:true},
            ArgDef{id:"to-alias", long:None, short:None, kind:ArgKind::PosSingle, display:"<to-alias>", required:true},
