    }
    AppSpec{canonical: Some(match sub {"add"=>"add","config-init"=>"config-init","copy"=>"copy","edit"=>"edit","list"=>"list","move"=>"move","remove"=>"remove","run"=>"run","show"=>"show",_=>unreachable!()}), defs}
}

pub fn canonical_subcommand(token: &[u8]) -> Option<&'static str> {
    match token {
        b"add" => Some("add"),
        b"config-init" | b"init" => Some("config-init"),
        b"copy" | b"cp" => Some("copy"),
        b"edit" => Some("edit"),
        b"help" => Some("help"),
        b"list" | b"ls" => Some("list"),
        b"move" | b"mv" | b"rename" => Some("move"),
        b"remove" | b"rm" => Some("remove"),
        b"run" => Some("run"),
        b"show" => Some("show"),
        _ => None,
    }
}

pub fn subcommand_candidates() -> Vec<String> {
    ["add","config-init","init","copy","cp","edit","help","list","ls","move","mv","rename","remove","rm","run","show"].iter().map(|s|s.to_string()).collect()
}

#[derive(Clone, Debug, Default)]
pub struct Parsed {
    pub occurrences: HashMap<String, usize>,
    pub values: HashMap<String, Vec<Bytes>>,
}
impl Parsed {
    pub fn add_occurrence(&mut self, id:&str){ *self.occurrences.entry(id.to_string()).or_insert(0)+=1; }
    pub fn occ(&self,id:&str)->usize{ *self.occurrences.get(id).unwrap_or(&0) }
    pub fn vals(&self,id:&str)->Vec<Bytes>{ self.values.get(id).cloned().unwrap_or_default() }
    pub fn first(&self,id:&str)->Option<Bytes>{ self.values.get(id).and_then(|v|v.first().cloned()) }
    pub fn add_value(&mut self,id:&str, v:Bytes){ self.values.entry(id.to_string()).or_default().push(v); }
    pub fn used_nonpos(&self, spec:&AppSpec)->HashSet<String>{
        let mut s=HashSet::new();
        for d in &spec.defs {
            if matches!(d.kind, ArgKind::Flag|ArgKind::OptSingle|ArgKind::OptMulti) && self.occ(d.id)>0 { s.insert(d.id.to_string()); }
        }
        s
    }
}

pub struct Ctx {
    pub bin: String,
    pub env_config_display: String, // for top help, lossy env value or ""
}

impl Ctx {
    pub fn print_help(&self, spec:&AppSpec, long:bool) -> ! {
        let text = match spec.canonical {
            None => help::top_help(&self.bin, &self.env_config_display, long),
            Some(c) => help::subcommand_help(&self.bin, c, long),
        };
        print_help_and_exit(text)
    }
    pub fn print_version(&self, spec:&AppSpec) -> ! {
        let text = match spec.canonical {
            None => "pier 0.1.6\n".to_string(),
            Some(c) => format!("{}-{} 0.1.6\n", self.bin, c),
        };
        print_version_and_exit(text)
    }
}

pub fn usage_for_error(spec:&AppSpec, bin:&str, used:&HashSet<String>) -> String {
    // included non-positional: required ones plus used
    let mut included: Vec<&ArgDef> = Vec::new();
    let mut has_nonrequired = false;
    for d in &spec.defs {
        if matches!(d.kind, ArgKind::Flag|ArgKind::OptSingle|ArgKind::OptMulti) {
            if d.required || used.contains(d.id) {
                if !d.required { has_nonrequired = true; }
                included.push(d);
            }
        }
    }
    if !has_nonrequired {
        return spec.full_usage(bin);
    }
    included.sort_by(|a,b| a.long.unwrap_or("").cmp(b.long.unwrap_or("")));
    let mut parts: Vec<String> = vec![spec.bin_prefix(bin)];
    for d in &spec.defs {
        if matches!(d.kind, ArgKind::PosSingle|ArgKind::PosMulti) && d.required {
            parts.push(d.display.to_string());
        }
    }
    for d in included { parts.push(d.display.to_string()); }
    format!("    {}", parts.join(" "))
}

pub fn clap_error_exit(body:&str, usage:&str) -> ! {
    let text = format!("error: {}\n\nUSAGE:\n{}\n\nFor more information try --help\n", body, usage);
    let _ = io::stderr().write_all(text.as_bytes());
    let _ = io::stderr().flush();
    std::process::exit(1)
}

pub fn err_unknown(ctx:&Ctx, spec:&AppSpec, parsed:&Parsed, arg_display:&str, suggestion:Option<&ArgDef>) -> ! {
    let mut body = format!("Found argument '{}' which wasn't expected, or isn't valid in this context", arg_display);
    let mut used = parsed.used_nonpos(spec);
    if let Some(sug) = suggestion {
        body.push_str(&format!("\n\tDid you mean \u{1b}[32m--\u{1b}[0m\u{1b}[32m{}\u{1b}[0m?", sug.long.unwrap_or("")));
        used.insert(sug.id.to_string());
    }
    let usage = usage_for_error(spec,&ctx.bin,&used);
    clap_error_exit(&body,&usage)
}

pub fn err_missing_required(ctx:&Ctx, spec:&AppSpec, parsed:&Parsed, missing:&[&ArgDef]) -> ! {
    let mut body = "The following required arguments were not provided:".to_string();
    for d in missing { body.push_str(&format!("\n    {}", d.display)); }
    let used = parsed.used_nonpos(spec);
    let usage = usage_for_error(spec,&ctx.bin,&used);
    clap_error_exit(&body,&usage)
}

pub fn err_duplicate(ctx:&Ctx, spec:&AppSpec, parsed:&Parsed, def:&ArgDef) -> ! {
    let body = format!("The argument '{}' was provided more than once, but cannot be used multiple times", def.display);
    let used = parsed.used_nonpos(spec);
    clap_error_exit(&body,&usage_for_error(spec,&ctx.bin,&used))
}
pub fn err_requires_value(ctx:&Ctx, spec:&AppSpec, parsed:&Parsed, def:&ArgDef) -> ! {
    let body = format!("The argument '{}' requires a value but none was supplied", def.display);
    let used = parsed.used_nonpos(spec);
    clap_error_exit(&body,&usage_for_error(spec,&ctx.bin,&used))
}

pub fn err_invalid_subcommand(ctx:&Ctx, top_parsed:&Parsed, token:&[u8], suggestion:&str) -> ! {
    let spec = top_spec();
    let tok = lossy(token);
    let body = format!("The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'", tok, suggestion, ctx.bin, tok);
    let used = top_parsed.used_nonpos(&spec);
    clap_error_exit(&body,&usage_for_error(&spec,&ctx.bin,&used))
}

fn suggest_long<'a>(spec:&'a AppSpec, name:&str) -> Option<&'a ArgDef> {
    let candidates: Vec<String> = spec.defs.iter().filter_map(|d| d.long.map(|l|l.to_string())).collect();
    if let Some(best) = did_you_mean(name,&candidates) {
        spec.defs.iter().find(|d| d.long==Some(best.as_str()))
    } else { None }
}

#[derive(Clone, Debug)]
enum Pending { Single(usize), Multi(usize) }

pub struct GenericParser<'a> {
    pub ctx:&'a Ctx,
    pub spec:&'a AppSpec,
    pub parsed: Parsed,
    pending: Option<Pending>,
    separator: bool,
}

impl<'a> GenericParser<'a> {
    pub fn new(ctx:&'a Ctx, spec:&'a AppSpec)->Self{ Self{ctx,spec,parsed:Parsed::default(),pending:None,separator:false} }
    fn is_flag_like(tok:&[u8])->bool{ tok.len()>1 && tok[0]==b'-' }
    pub fn parse_tokens(mut self, tokens:&[Bytes]) -> Parsed {
        for token in tokens {
            self.step(token.clone());
        }
        self.parsed
    }
    fn step(&mut self, token:Bytes){
        if let Some(p) = self.pending.clone() {
            if token==b"--" { self.pending=None; self.separator=true; return; }
            if Self::is_flag_like(&token) {
                self.pending=None;
                // fallthrough
            } else {
                let idx = match p { Pending::Single(i)|Pending::Multi(i)=>i };
                let id=self.spec.defs[idx].id;
                self.parsed.add_value(id, token);
                if matches!(p, Pending::Single(_)) { self.pending=None; }
                return;
            }
        }
        if self.separator { self.assign_positional(token); return; }
        if token==b"--" { self.separator=true; return; }
        if Self::is_flag_like(&token) {
            if token.len()>2 && token[1]==b'-' { self.process_long(&token); } else if token.len()>=2 && token[1]==b'-' && token.len()==2 { unreachable!() } else { self.process_short(&token); }
            return;
        }
        self.assign_positional(token);
    }
    fn assign_positional(&mut self, token:Bytes){
        for d in &self.spec.defs {
            match d.kind {
                ArgKind::PosSingle => {
                    if self.parsed.vals(d.id).is_empty() { let id=d.id; self.parsed.add_value(id,token); return; }
                }
                ArgKind::PosMulti => { let id=d.id; self.parsed.add_value(id,token); return; }
                _=>{}
            }
        }
        let disp=lossy(&token);
        err_unknown(self.ctx,self.spec,&self.parsed,&disp,None)
    }
    fn process_long(&mut self, token:&[u8]){
        // token starts with --
        let body=&token[2..];
        let eq = body.iter().position(|&b|b==b'=');
        let name_bytes = if let Some(e)=eq { &body[..e] } else { body };
        let name = match std::str::from_utf8(name_bytes){ Ok(s)=>s.to_owned(), Err(_)=> panic_fake(CLAP_PARSER_1632,"unexpected invalid UTF-8 code point") };
        if name=="help" { self.ctx.print_help(self.spec,true); }
        if name=="version" { self.ctx.print_version(self.spec); }
        let idx_opt = self.spec.defs.iter().position(|d| d.long==Some(name.as_str()));
        let Some(idx)=idx_opt else {
            let sug = suggest_long(self.spec,&name);
            let disp=format!("--{}",name);
            // Need to avoid borrow issues: clone suggestion def display info by finding again in err call path.
            // err_unknown expects Option<&ArgDef>; sug is ref into self.spec, fine.
            err_unknown(self.ctx,self.spec,&self.parsed,&disp,sug)
        };
        let def=self.spec.defs[idx].clone();
        self.parsed.add_occurrence(def.id);
        match def.kind {
            ArgKind::Flag=>{},
            ArgKind::OptSingle=>{
                if let Some(e)=eq { let v=body[e+1..].to_vec(); self.parsed.add_value(def.id,v); self.pending=None; }
                else { self.pending=Some(Pending::Single(idx)); }
            },
            ArgKind::OptMulti=>{
                if let Some(e)=eq { let v=body[e+1..].to_vec(); self.parsed.add_value(def.id,v); self.pending=None; }
                else { self.pending=Some(Pending::Multi(idx)); }
            },
            _=>{}
        }
    }
    fn process_short(&mut self, token:&[u8]){
        // token[0]=='-', not '--'
        let mut offset=1usize;
        while offset<token.len() {
            let (ch, ch_len, disp_ch) = decode_one(&token[offset..]);
            // help / version special
            if ch=='h' { self.ctx.print_help(self.spec,false); }
            if ch=='V' { self.ctx.print_version(self.spec); }
            let idx_opt=self.spec.defs.iter().position(|d| d.short==Some(ch));
            let Some(idx)=idx_opt else {
                let disp=format!("-{}",disp_ch);
                err_unknown(self.ctx,self.spec,&self.parsed,&disp,None)
            };
            let def=self.spec.defs[idx].clone();
            self.parsed.add_occurrence(def.id);
            match def.kind {
                ArgKind::Flag=>{ offset+=ch_len; continue; }
                ArgKind::OptSingle|ArgKind::OptMulti=>{
                    let rest=&token[offset+ch_len..];
                    if rest.is_empty() {
                        self.pending=Some(if matches!(def.kind,ArgKind::OptSingle){Pending::Single(idx)}else{Pending::Multi(idx)});
                    } else {
                        let has_eq=rest[0]==b'=';
                        let v=if has_eq { rest[1..].to_vec() } else { rest.to_vec() };
                        self.parsed.add_value(def.id,v);
                        if matches!(def.kind,ArgKind::OptMulti) && !has_eq { self.pending=Some(Pending::Multi(idx)); } else { self.pending=None; }
                    }
                    break;
                }
                _=>{ break; }
            }
        }
    }
}

pub fn decode_one(bytes:&[u8]) -> (char, usize, String) {
    if bytes.is_empty(){ return ('\0',0,String::new()) }
    match std::str::from_utf8(bytes) {
        Ok(s)=>{ let ch=s.chars().next().unwrap_or('\0'); (ch,ch.len_utf8(),ch.to_string()) }
        Err(e)=>{
            let valid=e.valid_up_to();
            if valid>0 {
                let s=std::str::from_utf8(&bytes[..valid]).unwrap();
                let ch=s.chars().next().unwrap();
                (ch,ch.len_utf8(),ch.to_string())
            } else {
                let l=e.error_len().unwrap_or(1);
                ('\u{fffd}',l,"\u{fffd}".to_string())
            }
        }
    }
}

// Validation for a generic app. insert_env is handled by caller for top.
pub fn validate_parsed(ctx:&Ctx, spec:&AppSpec, parsed:&Parsed, require_top_alias:bool){
    // missing required
    let mut missing:Vec<&ArgDef>=Vec::new();
    for d in &spec.defs {
        if !d.required { continue; }
        if spec.canonical.is_none() && d.id=="alias" && !require_top_alias { continue; }
        match d.kind {
            ArgKind::PosSingle|ArgKind::PosMulti=>{ if parsed.vals(d.id).is_empty(){missing.push(d);} }
            ArgKind::OptSingle|ArgKind::OptMulti|ArgKind::Flag=>{ if parsed.occ(d.id)==0 {missing.push(d);} }
        }
    }
    if !missing.is_empty(){ err_missing_required(ctx,spec,parsed,&missing); }
    // matched args
    for d in &spec.defs {
        // value validation for cmd_width
        if d.id=="cmd_width" {
            for v in parsed.vals(d.id) {
                let s=lossy(&v);
                if let Err(e)=s.parse::<usize>() {
                    let text=format!("error: Invalid value for '{}': {}\n", d.display, e);
                    let _=io::stderr().write_all(text.as_bytes());
                    std::process::exit(1);
                }
            }
        }
        // duplicate
        if matches!(d.kind, ArgKind::Flag|ArgKind::OptSingle) && parsed.occ(d.id)>1 {
            err_duplicate(ctx,spec,parsed,d);
        }
        // missing value
        if matches!(d.kind, ArgKind::OptSingle) && parsed.occ(d.id)>0 && parsed.vals(d.id).is_empty() {
            err_requires_value(ctx,spec,parsed,d);
        }
    }
}

// -------- Top-level parsing --------
pub enum TopOutcomeKind { AliasRun, Subcommand(String, Parsed), HelpTopic(Vec<Bytes>) }
pub struct TopOutcome {
    pub top_parsed: Parsed,
    pub kind: TopOutcomeKind,
}

pub fn parse_top(ctx:&Ctx, tokens:&[Bytes]) -> TopOutcome {
    let spec=top_spec();
    // We implement a custom loop by reusing GenericParser internals through a manual parser.
    let mut parser = GenericParser::new(ctx,&spec);
    // GenericParser fields are private to this module (same module), accessible.
    let mut i=0usize;
    while i<tokens.len() {
        let token=tokens[i].clone();
        // pending config option handling is inside GenericParser.step, but we need intercept positional/subcommand.
        // We replicate step logic adapted: If parser pending exists, just delegate to parser.step
        if parser.pending.is_some() {
            parser.step(token);
            i+=1; continue;
        }
        let args_started = !parser.parsed.vals("args").is_empty();
        if args_started {
            // did-you-mean check on this token
            check_top_candidate(ctx,&parser.parsed,&token);
            parser.parsed.add_value("args",token);
            i+=1; continue;
        }
        if parser.separator {
            check_top_candidate(ctx,&parser.parsed,&token);
            // assign alias or first arg
            if parser.parsed.vals("alias").is_empty() { parser.parsed.add_value("alias",token); } else { parser.parsed.add_value("args",token); }
            i+=1; continue;
        }
        if token==b"--" { parser.separator=true; i+=1; continue; }
        if GenericParser::is_flag_like(&token) {
            parser.step(token); i+=1; continue;
        }
        // plain token
        if let Some(canon)=canonical_subcommand(&token) {
            let remaining=tokens[i+1..].to_vec();
            if canon=="help" {
                return TopOutcome{top_parsed:parser.parsed, kind:TopOutcomeKind::HelpTopic(remaining)};
            }
            let subspec=spec_for(canon);
            let subparser=GenericParser::new(ctx,&subspec);
            let subparsed=subparser.parse_tokens(&remaining);
            return TopOutcome{top_parsed:parser.parsed, kind:TopOutcomeKind::Subcommand(canon.to_string(),subparsed)};
        }
        check_top_candidate(ctx,&parser.parsed,&token);
        if parser.parsed.vals("alias").is_empty() { parser.parsed.add_value("alias",token); } else { parser.parsed.add_value("args",token); }
        i+=1;
    }
    TopOutcome{top_parsed:parser.parsed, kind:TopOutcomeKind::AliasRun}
}

fn check_top_candidate(ctx:&Ctx, parsed:&Parsed, token:&[u8]){
    let tok=lossy(token);
    if let Some(sug)=did_you_mean(&tok,&subcommand_candidates()){
        err_invalid_subcommand(ctx,parsed,token,&sug);
    }
}

pub fn handle_help_topic(ctx:&Ctx, topics:&[Bytes]) -> ! {
    if topics.is_empty() {
        // main short help
        let spec=top_spec();
        ctx.print_help(&spec,false);
    }
    let first=&topics[0];
    let first_str=lossy(first);
    // recognize canonical or help
    let canon_opt = canonical_subcommand(first);
    match canon_opt {
        Some(canon)=>{
            if topics.len()>1 {
                let second=lossy(&topics[1]);
                let body=format!("The subcommand '{}' wasn't recognized",second);
                let usage=format!("\t{} help <subcommands>...",ctx.bin);
                clap_error_exit(&body,&usage);
            }
            if canon=="help" {
                print_help_and_exit(help::subcommand_help(&ctx.bin,"help",false));
            } else {
                let spec=spec_for(canon);
                ctx.print_help(&spec,false);
            }
        }
        None=>{
            let body=format!("The subcommand '{}' wasn't recognized",first_str);
            let usage=format!("\t{} help <subcommands>...",ctx.bin);
            clap_error_exit(&body,&usage);
        }
    }
}
