        insert_dotted(table,&keys,node,&ctx,line)?;
        Ok(())
    }

    fn parse_value(&mut self,ctx:String)->Result<Node,String>{
        let seq=self.next_seq();
        let start_line=self.line;
        self.skip_inline_ws();
        if self.eof(){ return Err(format!("unexpected eof encountered at line {}",self.line)); }
        let ch=self.peek().unwrap();
        let value=match ch {
            '"'|'\''=>{ let (s,_)=self.parse_string_token()?; Value::Str(s) }
            '['=>{ let arr=self.parse_array(ctx.clone())?; Value::Array(arr) }
