use std::collections::{BTreeMap, HashSet};

#[derive(Debug, Clone, Default)]
pub struct Script {
    pub command: String,
    pub description: Option<String>,
    pub tags: Option<Vec<String>>,
}
#[derive(Debug, Clone, Default)]
pub struct DefaultOpts {
    pub interpreter: Option<Vec<String>>,
    pub command_width: Option<usize>,
}
#[derive(Debug, Clone, Default)]
pub struct Config {
    pub scripts: BTreeMap<String, Script>,
    pub default: DefaultOpts,
}

// ---------- Internal TOML model ----------
#[derive(Debug, Clone)]
struct Node {
    value: Value,
    ctx: String,
    #[allow(dead_code)]
    line: usize,
    #[allow(dead_code)]
    seq: u64,
}
#[derive(Debug, Clone)]
enum Value {
    Str(String),
    Integer(i64),
    Float(f64),
    Bool(bool),
    Datetime(String),
    Array(Vec<Node>),
    Table(Box<TableData>),
    ArrayTables(Vec<TableData>),
}
#[derive(Debug, Clone)]
struct TableData {
    entries: Vec<Entry>,
    explicit: bool,
    inline: bool,
    dotted: bool,
    ctx: String,
    line: usize,
    #[allow(dead_code)]
    seq: u64,
}
impl TableData {
    fn new(ctx:String,line:usize,seq:u64)->Self{ Self{entries:Vec::new(),explicit:false,inline:false,dotted:false,ctx,line,seq} }
    fn last_idx(&self,key:&str)->Option<usize>{ self.entries.iter().rposition(|e|e.key==key) }
}
#[derive(Debug, Clone)]
struct Entry {
    key: String,
    node: Node,
    duplicate: bool,
}

fn ctx_join(parts:&[String])->String{ parts.join(".") }
fn escape_debug_char(c:char)->String{ c.escape_debug().to_string() }

struct Parser {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    seq: u64,
    root: TableData,
    current_path: Vec<String>,
}
impl Parser {
    fn new(input:&str)->Self{ Self{chars:input.chars().collect(),pos:0,line:1,seq:0,root:TableData::new(String::new(),1,0),current_path:Vec::new()} }
    fn next_seq(&mut self)->u64{ self.seq+=1; self.seq }
    fn eof(&self)->bool{ self.pos>=self.chars.len() }
    fn peek(&self)->Option<char>{ self.chars.get(self.pos).copied() }
    fn peek_at(&self,off:usize)->Option<char>{ self.chars.get(self.pos+off).copied() }
    fn starts_with(&self,s:&str)->bool{
        let v:Vec<char>=s.chars().collect();
        if self.pos+v.len()>self.chars.len(){return false}
        self.chars[self.pos..self.pos+v.len()]==v[..]
    }
    fn advance(&mut self)->Option<char>{
        let c=self.peek()?;
        self.pos+=1;
        if c=='\n'{self.line+=1;}
        Some(c)
    }
    fn consume_str(&mut self,s:&str)->bool{ if self.starts_with(s){ for _ in s.chars(){self.advance();} true } else {false} }
    fn skip_inline_ws(&mut self){ while matches!(self.peek(),Some(' '|'\t')){self.advance();} }
    fn skip_comment(&mut self){ if self.peek()==Some('#'){ while let Some(c)=self.peek(){ if c=='\n'{break;} self.pos+=1; } } }
    fn consume_newline(&mut self)->bool{
        if self.peek()==Some('\n'){self.advance(); true}
        else if self.peek()==Some('\r') && self.peek_at(1)==Some('\n'){self.advance(); self.advance(); true}
        else {false}
    }
    fn skip_blank(&mut self){
        loop{
            self.skip_inline_ws();
            if self.peek()==Some('#'){ self.skip_comment(); }
            if self.consume_newline(){ continue; }
            break;
        }
    }
    fn skip_array_ws(&mut self){
        loop{
            while matches!(self.peek(),Some(' '|'\t'|'\n')){self.advance();}
            if self.peek()==Some('\r') && self.peek_at(1)==Some('\n'){self.advance(); self.advance(); continue;}
            if self.peek()==Some('#'){ self.skip_comment(); continue; }
            break;
        }
    }
    fn found_desc(&self)->String{
        if self.eof(){return "eof".to_string()}
        match self.peek().unwrap() {
            '\n' => "a newline".to_string(),
            '\r' if self.peek_at(1)==Some('\n') => "a newline".to_string(),
            '=' => "an equals".to_string(),
            '.' => "a period".to_string(),
            ',' => "a comma".to_string(),
            ':' => "a colon".to_string(),
            ']' => "a right bracket".to_string(),
            '[' => "a left bracket".to_string(),
            '}' => "a right brace".to_string(),
            '{' => "a left brace".to_string(),
            '#' => "a comment".to_string(),
            '"'|'\'' => "a string".to_string(),
            _ => "an identifier".to_string(),
        }
    }
    fn is_unexpected(&self)->bool{
        if self.eof(){return false}
        let c=self.peek().unwrap();
        if c.is_control() { return true; }
        !(c.is_alphanumeric() || matches!(c,'_'|'-'|'+'|'='|'.'|','|':'|']'|'['|'}'|'{'|'#'|'"'|'\''|'\n'))
    }
    fn err_expected(&self,what:&str)->String{
        if !self.eof() && self.is_unexpected() {
            format!("unexpected character found: `{}` at line {}", escape_debug_char(self.peek().unwrap()), self.line)
        } else {
            format!("expected {}, found {} at line {}", what, self.found_desc(), self.line)
        }
    }
    fn err_expected_at(&self,what:&str,line:usize)->String{
        // currently only used where line is current in practice
        let _=line; self.err_expected(what)
    }
    fn expect_line_end(&mut self)->Result<(),String>{
        self.skip_inline_ws();
        if self.eof(){return Ok(())}
        if self.peek()==Some('#'){ self.skip_comment(); if self.eof(){return Ok(())} if self.consume_newline(){return Ok(())} return Ok(()) }
        if self.consume_newline(){return Ok(())}
        Err(self.err_expected("newline"))
    }

    fn parse_document(&mut self)->Result<(),String>{
        if self.peek()==Some('\u{feff}'){self.advance();}
        loop{
            self.skip_blank();
            if self.eof(){break;}
            if self.peek()==Some('['){ self.parse_header()?; }
            else { self.parse_key_value()?; }
        }
        Ok(())
    }

    fn parse_key_path(&mut self)->Result<Vec<String>,String>{
        let mut keys=Vec::new();
        loop{
            self.skip_inline_ws();
            let key=self.parse_key()?;
            keys.push(key);
            self.skip_inline_ws();
            if self.peek()==Some('.'){ self.advance(); continue; }
            break;
        }
        Ok(keys)
    }
    fn parse_key(&mut self)->Result<String,String>{
        self.skip_inline_ws();
        match self.peek() {
            Some('"')=>{ let (s,_) = self.parse_string_token()?; Ok(s) }
            Some('\'')=>{ let (s,_) = self.parse_string_token()?; Ok(s) }
            Some(c) if c.is_ascii_alphanumeric() || c=='_' || c=='-' => {
                let mut s=String::new();
                while let Some(ch)=self.peek(){ if ch.is_ascii_alphanumeric()||ch=='_'||ch=='-'{s.push(ch); self.advance();} else {break;} }
                Ok(s)
            }
            _=> Err(self.err_expected("a table key"))
        }
    }

    fn parse_header(&mut self)->Result<(),String>{
        let header_line=self.line;
        self.advance(); // [
        let is_array = if self.peek()==Some('['){self.advance(); true}else{false};
        let keys=self.parse_key_path()?;
        self.skip_inline_ws();
        if self.peek()!=Some(']'){ return Err(self.err_expected("a right bracket")); }
        self.advance();
        if is_array {
            if self.peek()!=Some(']'){ return Err(self.err_expected("a right bracket")); }
            self.advance();
        }
        self.expect_line_end()?;
        self.apply_header(keys.clone(),is_array,header_line)?;
        self.current_path=keys;
        Ok(())
    }

    fn header_ctxs(path:&[String])->Vec<String>{
        let mut out=Vec::new(); let mut cur:Vec<String>=Vec::new();
        for p in path{cur.push(p.clone()); out.push(ctx_join(&cur));}
        out
    }
    fn apply_header(&mut self,path:Vec<String>,is_array:bool,line:usize)->Result<(),String>{
        let full=ctx_join(&path);
        let ctxs=Self::header_ctxs(&path);
        let seq=self.next_seq();
        if is_array {
            // navigate parent
            let (parent_path,last)=path.split_at(path.len()-1);
            let parent_ctxs=&ctxs[..ctxs.len()-1];
            // We need borrow root mutably via helper
            let root=&mut self.root;
            let parent=get_or_create_table(root,parent_path,parent_ctxs,seq,line,"")?;
            if let Some(idx)=parent.last_idx(&last[0]) {
                match &mut parent.entries[idx].node.value {
                    Value::ArrayTables(arr)=>{ arr.push(TableData::new(full.clone(),line,seq)); Ok(()) }
                    _=> Err(format!("redefinition of table `{}` for key `{}` at line {}",full,full,line))
                }
            } else {
                let node=Node{value:Value::ArrayTables(vec![TableData::new(full.clone(),line,seq)]),ctx:full.clone(),line,seq};
                parent.entries.push(Entry{key:last[0].clone(),node,duplicate:false});
                Ok(())
            }
        } else {
            let root=&mut self.root;
            // navigate to parent then final manually
            let (parent_path,last)=path.split_at(path.len()-1);
            let parent_ctxs=&ctxs[..ctxs.len()-1];
            let parent=get_or_create_table(root,parent_path,parent_ctxs,seq,line,"")?;
            if let Some(idx)=parent.last_idx(&last[0]) {
                match &mut parent.entries[idx].node.value {
                    Value::Table(td)=>{
                        if td.explicit || td.inline {
                            Err(format!("redefinition of table `{}` for key `{}` at line {}",full,full,line))
                        } else { td.explicit=true; td.dotted=false; Ok(()) }
                    }
                    _=> Err(format!("redefinition of table `{}` for key `{}` at line {}",full,full,line))
                }
            } else {
                let mut td=TableData::new(full.clone(),line,seq); td.explicit=true;
                let node=Node{value:Value::Table(Box::new(td)),ctx:full.clone(),line,seq};
                parent.entries.push(Entry{key:last[0].clone(),node,duplicate:false});
                Ok(())
            }
        }
    }

    fn parse_key_value(&mut self)->Result<(),String>{
        let keys=self.parse_key_path()?;
        self.skip_inline_ws();
        if self.peek()!=Some('='){ return Err(self.err_expected("an equals")); }
        self.advance();
        self.skip_inline_ws();
        let ctx = if self.current_path.is_empty() { keys[0].clone() } else { let mut p=self.current_path.clone(); p.push(keys[0].clone()); ctx_join(&p) };
        let node=self.parse_value(ctx.clone())?;
        self.expect_line_end()?;
        // insert
        let current=self.current_path.clone();
        let ctxs=Self::header_ctxs(&current);
        let seq=self.next_seq();
        let line=self.line;
        let root=&mut self.root;
        let table=get_or_create_table(root,&current,&ctxs,seq,line,"")?;
        insert_dotted(table,&keys,node,&ctx,line)?;
        Ok(())
    }

    fn parse_value(&mut self,ctx:String)->Result<Node,String>{
        let seq=self.next_seq();
        let start_line=self.line;
        self.skip_inline_ws();
        if self.eof(){ return Err(format!("unexpected eof encountered at line {}",self.line)); }
        let ch=self.peek().unwrap();
        let value=match ch {
            '"'|'\''=>{ let (s,_)=self.parse_string_token()?; Value::Str(s) }
            '['=>{ let arr=self.parse_array(ctx.clone())?; Value::Array(arr) }
            '{'=>{ let td=self.parse_inline_table(ctx.clone())?; Value::Table(Box::new(td)) }
            '.'=>{ return Err(self.err_expected("a value")); }
            '#'=>{ return Err(self.err_expected("a value")); }
            c if c.is_ascii_alphanumeric() || matches!(c,'+'|'-'|'_') => { self.parse_bare_value()? }
            ','|']'|'}'|'='|':' => { return Err(self.err_expected("a value")); }
            _=>{ return Err(self.err_expected("a value")); }
        };
        Ok(Node{value,ctx,line:start_line,seq})
    }

    fn parse_array(&mut self,ctx:String)->Result<Vec<Node>,String>{
        self.advance(); // [
        let mut nodes=Vec::new();
        let mut first_cat:Option<&'static str>=None;
        let mut after_comma=false;
        loop{
            self.skip_array_ws();
            if self.eof(){
                // expecting a value at start or after comma
                return Err(format!("unexpected eof encountered at line {}",self.line));
            }
            if self.peek()==Some(']'){ self.advance(); break; }
            let elem_line=self.line;
            let node=self.parse_value(ctx.clone())?;
            let cat=category(&node.value);
            if let Some(fc)=first_cat { if fc!=cat { return Err(format!("mixed types in an array at line {}",elem_line)); } } else { first_cat=Some(cat); }
            nodes.push(node);
            after_comma=false;
            self.skip_array_ws();
            if self.eof(){ return Err(self.err_expected("a right bracket")); }
            if self.peek()==Some(','){ self.advance(); after_comma=true; continue; }
            if self.peek()==Some(']'){ self.advance(); break; }
            return Err(self.err_expected("a right bracket"));
        }
        let _=after_comma;
        Ok(nodes)
    }

    fn parse_inline_table(&mut self,ctx:String)->Result<TableData,String>{
        let seq=self.next_seq(); let line=self.line;
        self.advance(); // {
        let mut td=TableData::new(ctx.clone(),line,seq); td.inline=true; td.explicit=true;
        self.skip_inline_ws();
        if self.peek()==Some('}'){ self.advance(); return Ok(td); }
        loop{
            let keys=self.parse_key_path()?;
            self.skip_inline_ws();
            if self.peek()!=Some('='){ return Err(self.err_expected("an equals")); }
            self.advance(); self.skip_inline_ws();
            let node=self.parse_value(ctx.clone())?;
            insert_dotted(&mut td,&keys,node,&ctx,self.line)?;
            self.skip_inline_ws();
            if self.peek()==Some('}'){ self.advance(); break; }
            if self.peek()==Some(','){ self.advance(); self.skip_inline_ws(); continue; }
            return Err(self.err_expected("a comma"));
        }
        Ok(td)
    }

    // Strings: returns content and whether multiline
    fn parse_string_token(&mut self)->Result<(String,bool),String>{
        let start_line=self.line;
        if self.starts_with("\"\"\"") {
            self.pos+=3; // no newlines
            if self.peek()==Some('\n'){self.advance();} else if self.peek()==Some('\r') && self.peek_at(1)==Some('\n'){self.advance(); self.advance();}
            let mut out=String::new();
            loop{
                if self.eof(){ return Err(format!("unterminated string at line {}",start_line)); }
                // closing runs
                if self.peek()==Some('"') {
                    // count run
                    let mut cnt=0usize; while self.peek_at(cnt)==Some('"'){cnt+=1;}
                    if cnt>=3 {
                        if cnt==3 { for _ in 0..3{self.advance();} break; }
                        if cnt==4 { out.push('"'); for _ in 0..4{self.advance();} break; }
                        if cnt==5 { out.push('"'); out.push('"'); for _ in 0..5{self.advance();} break; }
                        // >=6: close at 3
                        for _ in 0..3{self.advance();} break;
                    }
                }
                let c=self.peek().unwrap();
                if c=='\\' {
                    // line-ending backslash?
                    if self.is_line_ending_backslash() {
                        self.consume_line_ending_backslash();
                        continue;
                    }
                    let decoded=self.parse_escape(start_line)?; out.push(decoded); continue;
                }
                if c=='\r' && self.peek_at(1)==Some('\n'){ out.push('\n'); self.advance(); self.advance(); continue; }
                if c!='\n' && c.is_control(){ return Err(format!("invalid character in string: `{}` at line {}",escape_debug_char(c),self.line)); }
                out.push(c); self.advance();
            }
            return Ok((out,true));
        }
        if self.starts_with("'''") {
            self.pos+=3;
            if self.peek()==Some('\n'){self.advance();} else if self.peek()==Some('\r') && self.peek_at(1)==Some('\n'){self.advance(); self.advance();}
            let mut out=String::new();
            loop{
                if self.eof(){ return Err(format!("unterminated string at line {}",start_line)); }
                if self.peek()==Some('\'') {
                    let mut cnt=0usize; while self.peek_at(cnt)==Some('\''){cnt+=1;}
                    if cnt>=3 {
                        if cnt==3 { for _ in 0..3{self.advance();} break; }
                        if cnt==4 { out.push('\''); for _ in 0..4{self.advance();} break; }
                        if cnt==5 { out.push('\''); out.push('\''); for _ in 0..5{self.advance();} break; }
                        for _ in 0..3{self.advance();} break;
                    }
                }
                let c=self.peek().unwrap();
                if c=='\r' && self.peek_at(1)==Some('\n'){ out.push('\n'); self.advance(); self.advance(); continue; }
                if c!='\n' && c!='\t' && c.is_control(){ return Err(format!("invalid character in string: `{}` at line {}",escape_debug_char(c),self.line)); }
                out.push(c); self.advance();
            }
            return Ok((out,true));
        }
        if self.peek()==Some('"') {
            self.advance();
            let mut out=String::new();
            loop{
                if self.eof(){ return Err(format!("unterminated string at line {}",start_line)); }
                let c=self.peek().unwrap();
                if c=='\n'{ return Err(format!("newline in string found at line {}",self.line)); }
                if c=='"'{ self.advance(); break; }
                if c=='\\'{ let d=self.parse_escape(start_line)?; out.push(d); continue; }
                if c.is_control(){ return Err(format!("invalid character in string: `{}` at line {}",escape_debug_char(c),self.line)); }
                out.push(c); self.advance();
            }
            return Ok((out,false));
        }
        if self.peek()==Some('\'') {
            self.advance();
            let mut out=String::new();
            loop{
                if self.eof(){ return Err(format!("unterminated string at line {}",start_line)); }
                let c=self.peek().unwrap();
                if c=='\n'{ return Err(format!("newline in string found at line {}",self.line)); }
                if c=='\''{ self.advance(); break; }
                if c!='\t' && c.is_control(){ return Err(format!("invalid character in string: `{}` at line {}",escape_debug_char(c),self.line)); }
                out.push(c); self.advance();
            }
            return Ok((out,false));
        }
        Err(self.err_expected("a string"))
    }
    fn is_line_ending_backslash(&self)->bool{
        if self.peek()!=Some('\\'){return false}
        let mut i=self.pos+1;
        while i<self.chars.len() && (self.chars[i]==' '||self.chars[i]=='\t'){i+=1;}
        i<self.chars.len() && (self.chars[i]=='\n' || (self.chars[i]=='\r' && i+1<self.chars.len() && self.chars[i+1]=='\n'))
    }
    fn consume_line_ending_backslash(&mut self){
        self.advance(); // backslash
        self.skip_inline_ws();
        self.consume_newline();
        loop{
            while matches!(self.peek(),Some(' '|'\t'|'\n')){self.advance();}
            if self.peek()==Some('\r') && self.peek_at(1)==Some('\n'){self.advance(); self.advance(); continue;}
            break;
        }
    }
    fn parse_escape(&mut self,start_line:usize)->Result<char,String>{
        // current \ 
        self.advance();
        if self.eof(){ return Err(format!("unterminated string at line {}",start_line)); }
        let c=self.peek().unwrap();
        let line=self.line;
        let simple=match c {
            'b'=>Some('\u{8}'), 't'=>Some('\t'), 'n'=>Some('\n'), 'f'=>Some('\u{c}'), 'r'=>Some('\r'), '"'=>Some('"'), '\\'=>Some('\\'), _=>None
        };
        if let Some(v)=simple{ self.advance(); return Ok(v); }
        if c=='u' || c=='U' {
            let n=if c=='u'{4}else{8};
            self.advance();
            let mut val:u32=0;
            for _ in 0..n {
                if self.eof(){ return Err(format!("unterminated string at line {}",start_line)); }
                let h=self.peek().unwrap();
                if let Some(d)=h.to_digit(16){ val=val*16+d; self.advance(); }
                else { return Err(format!("invalid hex escape character in string: `{}` at line {}",escape_debug_char(h),line)); }
            }
            if let Some(ch)=char::from_u32(val){ return Ok(ch); }
            else { return Err(format!("invalid hex escape character in string: `{}` at line {}",escape_debug_char(c),line)); }
        }
        Err(format!("invalid escape character in string: `{}` at line {}",escape_debug_char(c),line))
    }

    fn parse_bare_value(&mut self)->Result<Value,String>{
        let start=self.pos; let start_line=self.line;
        while let Some(c)=self.peek(){
            if matches!(c,' '|'\t'|'\n'|'\r'|','|']'|'}'|'#'|';'){break;}
            self.pos+=1;
        }
        let mut token:String=self.chars[start..self.pos].iter().collect();
        // possible date + space + time
        if is_date_like(&token) && self.peek()==Some(' ') {
            // lookahead a second token
            let saved=self.pos;
            self.pos+=1;
            let tstart=self.pos;
            while let Some(c)=self.peek(){ if matches!(c,' '|'\t'|'\n'|'\r'|','|']'|'}'|'#'|';'){break;} self.pos+=1; }
            let second:String=self.chars[tstart..self.pos].iter().collect();
            if second.contains(':') && second.chars().next().map(|c|c.is_ascii_digit()).unwrap_or(false) {
                token.push(' '); token.push_str(&second);
            } else {
                self.pos=saved;
            }
        }
        if token=="true"{return Ok(Value::Bool(true));}
        if token=="false"{return Ok(Value::Bool(false));}
        if is_datetime_token(&token) {
            if let Some(err)=self.check_incomplete_time(&token){ return Err(err); }
            return Ok(Value::Datetime(token));
        }
        parse_number_token(&token,start_line)
    }
    fn check_incomplete_time(&self,token:&str)->Option<String>{
        let segment = if let Some(pos)=token.rfind(|c|c=='T'||c=='t'||c==' ') { &token[pos+1..] } else if token.contains(':') && !token.contains('-') { token } else { "" };
        if !segment.is_empty() && segment.matches(':').count()==1 {
            Some(self.err_expected("a colon"))
        } else { None }
    }
}

fn category(v:&Value)->&'static str{
    match v{ Value::Str(_)=>"string",Value::Integer(_)=>"integer",Value::Float(_)=>"float",Value::Bool(_)=>"bool",Value::Datetime(_)=>"datetime",Value::Array(_)|Value::ArrayTables(_)=>"array",Value::Table(_)=>"table" }
}

fn get_or_create_table<'a>(table:&'a mut TableData,path:&[String],ctxs:&[String],seq:u64,line:usize,_unused:&str)->Result<&'a mut TableData,String>{
    if path.is_empty(){ return Ok(table); }
    let key=&path[0];
    let idx=if let Some(i)=table.last_idx(key){i}else{
        let ctx=ctxs.get(0).cloned().unwrap_or_else(||key.clone());
        let mut td=TableData::new(ctx.clone(),line,seq);
        td.ctx=ctx.clone();
        let node=Node{value:Value::Table(Box::new(td)),ctx,line,seq};
        table.entries.push(Entry{key:key.clone(),node,duplicate:false});
        table.entries.len()-1
    };
    match &mut table.entries[idx].node.value {
        Value::Table(inner)=> get_or_create_table(inner,&path[1..],&ctxs[usize::min(1,ctxs.len())..],seq,line,_unused),
        Value::ArrayTables(arr)=>{
            if arr.is_empty(){ arr.push(TableData::new(ctxs.get(0).cloned().unwrap_or_default(),line,seq)); }
            let last=arr.last_mut().unwrap();
            get_or_create_table(last,&path[1..],&ctxs[usize::min(1,ctxs.len())..],seq,line,_unused)
        }
        _=>{
            let full=ctxs.get(0).cloned().unwrap_or_else(||key.clone());
            Err(format!("redefinition of table `{}` for key `{}` at line {}",full,full,line))
        }
    }
}

fn insert_dotted(table:&mut TableData,keys:&[String],node:Node,ctx:&str,line:usize)->Result<(),String>{
    if keys.len()==1 {
        let dup=table.last_idx(&keys[0]).is_some();
        table.entries.push(Entry{key:keys[0].clone(),node,duplicate:dup});
        return Ok(());
    }
    let first=&keys[0];
    let idx=if let Some(i)=table.last_idx(first){i}else{
        let mut td=TableData::new(ctx.to_string(),line,node.seq); td.dotted=true;
        let n=Node{value:Value::Table(Box::new(td)),ctx:ctx.to_string(),line,seq:node.seq};
        table.entries.push(Entry{key:first.clone(),node:n,duplicate:false});
        table.entries.len()-1
    };
    match &mut table.entries[idx].node.value {
        Value::Table(inner)=> insert_dotted(inner,&keys[1..],node,ctx,line),
        Value::ArrayTables(arr)=>{
            if let Some(last)=arr.last_mut(){ insert_dotted(last,&keys[1..],node,ctx,line) } else { Err(format!("redefinition of table `{}` for key `{}` at line {}",ctx,ctx,line)) }
        }
        _=> Err(format!("redefinition of table `{}` for key `{}` at line {}",ctx,ctx,line))
    }
}

fn is_date_like(token:&str)->bool{
    let parts:Vec<&str>=token.split('-').collect();
    parts.len()>=3 && token.chars().next().map(|c|c.is_ascii_digit()).unwrap_or(false)
}
fn is_datetime_token(token:&str)->bool{
    if token.starts_with('T'){ return true; }
    let first=token.chars().next();
    if !matches!(first,Some(c) if c.is_ascii_digit()){return false;}
    // a '-' after initial digits (not exponent) or a ':'
    if token.contains(':'){return true;}
    // find '-' not after e/E
    let chars:Vec<char>=token.chars().collect();
    for i in 1..chars.len(){ if chars[i]=='-' && chars[i-1]!='e' && chars[i-1]!='E'{ return true; } }
    false
}

fn validate_digit_underscores(part:&str)->bool{
    if part.is_empty(){return false}
    let chars:Vec<char>=part.chars().collect();
    if !chars[0].is_ascii_digit() || !chars[chars.len()-1].is_ascii_digit(){return false}
    let mut prev_us=false;
    for &c in &chars{
        if c=='_'{ if prev_us{return false;} prev_us=true; }
        else if c.is_ascii_digit(){prev_us=false;}
        else{return false;}
    }
    true
}
fn parse_number_token(token:&str,line:usize)->Result<Value,String>{
    let err=||format!("invalid number at line {}",line);
    match token {
        "inf"|"+inf"=>return Ok(Value::Float(f64::INFINITY)),
        "-inf"=>return Ok(Value::Float(f64::NEG_INFINITY)),
        "nan"|"+nan"|"-nan"=>return Ok(Value::Float(f64::NAN)),
        _=>{}
    }
    // non decimal
    if let Some(rest)=token.strip_prefix("0x"){
        if rest.is_empty() || !rest.chars().all(|c|c.is_ascii_hexdigit()||c=='_') || rest.starts_with('_')||rest.ends_with('_')||rest.contains("__"){return Err(err())}
        let cleaned=rest.replace('_',"");
        if let Ok(v)=u64::from_str_radix(&cleaned,16){ if v<=i64::MAX as u64{return Ok(Value::Integer(v as i64))} }
        return Err(err());
    }
    if let Some(rest)=token.strip_prefix("0o"){
        if rest.is_empty() || !rest.chars().all(|c|('0'..='7').contains(&c)||c=='_') || rest.starts_with('_')||rest.ends_with('_')||rest.contains("__"){return Err(err())}
        let cleaned=rest.replace('_',"");
        if let Ok(v)=u64::from_str_radix(&cleaned,8){ if v<=i64::MAX as u64{return Ok(Value::Integer(v as i64))} }
        return Err(err());
    }
    if let Some(rest)=token.strip_prefix("0b"){
        if rest.is_empty() || !rest.chars().all(|c|c=='0'||c=='1'||c=='_') || rest.starts_with('_')||rest.ends_with('_')||rest.contains("__"){return Err(err())}
        let cleaned=rest.replace('_',"");
        if let Ok(v)=u64::from_str_radix(&cleaned,2){ if v<=i64::MAX as u64{return Ok(Value::Integer(v as i64))} }
        return Err(err());
    }
    // decimal: validate roughly
    let mut s=token;
    if s.starts_with('+')||s.starts_with('-'){ s=&s[1..]; if s.is_empty(){return Err(err())} }
    // token body s may contain e/E . _ digits
    // split exponent
    let mut mantissa=s;
    let mut is_float=false;
    if let Some(epos)=s.find(['e','E']) {
        is_float=true;
        mantissa=&s[..epos];
        let exp=&s[epos+1..];
        let exp_digits=if exp.starts_with('+')||exp.starts_with('-'){&exp[1..]}else{exp};
        if !validate_digit_underscores(exp_digits){return Err(err())}
        if mantissa.contains('e')||mantissa.contains('E'){return Err(err())}
    }
    let int_part;
    if let Some(dpos)=mantissa.find('.') {
        is_float=true;
        int_part=&mantissa[..dpos];
        let frac=&mantissa[dpos+1..];
        if frac.contains('.'){return Err(err())}
        if !validate_digit_underscores(frac){return Err(err())}
    } else { int_part=mantissa; }
    if !validate_digit_underscores(int_part){return Err(err())}
    let int_digits:int_part = int_part.replace('_',"");
    if int_digits.len()>1 && int_digits.starts_with('0'){return Err(err())}
    let cleaned=token.replace('_',"");
    if is_float {
        match cleaned.parse::<f64>(){ Ok(v)=>{ if v.is_finite(){Ok(Value::Float(v))}else{Err(err())} }, Err(_)=>Err(err()) }
    } else {
        match cleaned.parse::<i64>(){ Ok(v)=>Ok(Value::Integer(v)), Err(_)=>Err(err()) }
    }
}

// ---------- Mapping ----------
fn unexpected(v:&Value)->String{
    match v{
        Value::Str(s)=>format!("string {:?}",s),
        Value::Integer(i)=>format!("integer `{}`",i),
        Value::Float(f)=>format!("floating point `{}`",f),
        Value::Bool(b)=>format!("boolean `{}`",b),
        Value::Datetime(_)=>"map".to_string(),
        Value::Array(_)|Value::ArrayTables(_)=>"sequence".to_string(),
        Value::Table(_)=>"map".to_string(),
    }
}
fn err_invalid_type(v:&Value,expected:&str,ctx:&str)->String{
    if ctx.is_empty(){ format!("invalid type: {}, expected {}",unexpected(v),expected) }
    else{ format!("invalid type: {}, expected {} for key `{}`",unexpected(v),expected,ctx) }
}
fn err_with_ctx(msg:String,ctx:&str)->String{
    if ctx.is_empty(){msg}else{format!("{} for key `{}`",msg,ctx)}
}
fn to_string_val(node:&Node)->Result<String,String>{
    match &node.value{ Value::Str(s)=>Ok(s.clone()), v=>Err(err_invalid_type(v,"a string",&node.ctx)) }
}
fn to_string_with_ctx(v:&Value,ctx:&str)->Result<String,String>{
    match v{ Value::Str(s)=>Ok(s.clone()), _=>Err(err_invalid_type(v,"a string",ctx)) }
}
fn to_string_vec(node:&Node)->Result<Vec<String>,String>{
    match &node.value{
        Value::Array(elems)=>{
            let mut out=Vec::new();
            for e in elems{ out.push(to_string_val(e)?); }
            Ok(out)
        }
        Value::ArrayTables(tables)=>{
            // sequence whose elements are tables; first element (if any) will fail as string
            if tables.is_empty(){ Ok(Vec::new()) } else { Err(err_invalid_type(&Value::Table(Box::new(tables[0].clone())),"a string",&node.ctx)) }
        }
        v=>Err(err_invalid_type(v,"a sequence",&node.ctx))
    }
}
fn to_usize(node:&Node)->Result<usize,String>{
    match &node.value{
        Value::Integer(i)=>{ if *i>=0{Ok(*i as usize)}else{Err(err_with_ctx(format!("invalid value: integer `{}`, expected usize",i),&node.ctx))} }
        v=>Err(err_invalid_type(v,"usize",&node.ctx))
    }
}

fn script_from_table(td:&TableData,ctx:&str)->Result<Script,String>{
    let mut script=Script::default();
    let mut seen:HashSet<String>=HashSet::new();
    let mut have_command=false;
    for entry in &td.entries {
        match entry.key.as_str(){
            "command"|"description"|"tags"=>{
                if seen.contains(&entry.key){ return Err(err_with_ctx(format!("duplicate field `{}`",entry.key),ctx)); }
                seen.insert(entry.key.clone());
                match entry.key.as_str(){
                    "command"=>{ script.command=to_string_val(&entry.node)?; have_command=true; }
                    "description"=>{ script.description=Some(to_string_val(&entry.node)?); }
                    "tags"=>{ script.tags=Some(to_string_vec(&entry.node)?); }
                    _=>{}
                }
            }
            _=>{}
        }
    }
    if !have_command{ return Err(err_with_ctx("missing field `command`".to_string(),ctx)); }
    Ok(script)
}
fn default_from_table(td:&TableData,ctx:&str)->Result<DefaultOpts,String>{
    let mut d=DefaultOpts::default();
    let mut seen:HashSet<String>=HashSet::new();
    for entry in &td.entries{
        match entry.key.as_str(){
            "interpreter"|"command_width"=>{
                if seen.contains(&entry.key){ return Err(err_with_ctx(format!("duplicate field `{}`",entry.key),ctx)); }
                seen.insert(entry.key.clone());
                if entry.key=="interpreter"{ d.interpreter=Some(to_string_vec(&entry.node)?); }
                else{ d.command_width=Some(to_usize(&entry.node)?); }
            }
            _=>{}
        }
    }
    Ok(d)
}

fn to_script(node:&Node)->Result<Script,String>{
    match &node.value{
        Value::Table(td)=> script_from_table(td,&node.ctx),
        Value::Array(elems)=>{
            for (i,e) in elems.iter().enumerate(){
                if i<3 { to_string_val(e)?; }
                else if i==3 { to_string_vec(e)?; }
                else { break; }
            }
            if elems.len()<4 { return Err(err_with_ctx(format!("invalid length {}, expected struct Script with 4 elements",elems.len()),&node.ctx)); }
            // unreachable in valid TOML due mixed-type arrays; construct a plausible value
            Ok(Script{command:to_string_val(&elems[1]).unwrap_or_default(),description:Some(to_string_val(&elems[2]).unwrap_or_default()),tags:Some(to_string_vec(&elems[3]).unwrap_or_default())})
        }
        Value::ArrayTables(tables)=>{
            if tables.is_empty(){ return Err(err_with_ctx("invalid length 0, expected struct Script with 4 elements".to_string(),&node.ctx)); }
            Err(err_invalid_type(&Value::Table(Box::new(tables[0].clone())),"a string",&node.ctx))
        }
        Value::Datetime(_)=> Err(err_with_ctx("missing field `command`".to_string(),&node.ctx)),
        v=> Err(err_invalid_type(v,"struct Script",&node.ctx)),
    }
}

fn to_default(node:&Node)->Result<DefaultOpts,String>{
    match &node.value{
        Value::Table(td)=> default_from_table(td,&node.ctx),
        Value::Array(elems)=>{
            for (i,e) in elems.iter().enumerate(){
                if i==0 { to_string_vec(e)?; }
                else if i==1 { to_usize(e)?; }
                else {break;}
            }
            if elems.len()<2 { return Err(err_with_ctx(format!("invalid length {}, expected struct ConfigDefaultOpts with 2 elements",elems.len()),&node.ctx)); }
            Ok(DefaultOpts{interpreter:Some(to_string_vec(&elems[0]).unwrap_or_default()),command_width:Some(to_usize(&elems[1]).unwrap_or_default())})
        }
        Value::ArrayTables(tables)=>{
            if tables.is_empty(){ return Err(err_with_ctx("invalid length 0, expected struct ConfigDefaultOpts with 2 elements".to_string(),&node.ctx)); }
            // first field expects seq of strings; a table element as sequence... mimic observed for [[1]] style by using tables as seq content conversion: first table converted as interpreter seq will be map expected seq
            Err(err_invalid_type(&Value::Table(Box::new(tables[0].clone())),"a sequence",&node.ctx))
        }
        Value::Datetime(_)=> Ok(DefaultOpts::default()),
        v=> Err(err_invalid_type(v,"struct ConfigDefaultOpts",&node.ctx)),
    }
}

fn to_scripts(node:&Node)->Result<BTreeMap<String,Script>,String>{
    match &node.value{
        Value::Table(td)=>{
            let mut map=BTreeMap::new();
            for entry in &td.entries{
                let script=to_script(&entry.node)?;
                map.insert(entry.key.clone(),script);
            }
            Ok(map)
        }
        Value::Datetime(raw)=>{
            Err(format!("invalid type: string {:?}, expected struct Script for key `{}`",raw,node.ctx))
        }
        v=> Err(err_invalid_type(v,"map is expected",&node.ctx))
    }
}

pub fn parse_config(input:&str)->Result<Config,String>{
    let mut parser=Parser::new(input);
    parser.parse_document()?;
    let root=parser.root;
    let mut cfg=Config::default();
    let mut seen:HashSet<String>=HashSet::new();
    for entry in &root.entries{
        match entry.key.as_str(){
            "scripts"=>{
                if entry.duplicate || seen.contains("scripts") && entry.duplicate {
                    return Err("duplicate field `scripts`".to_string());
                }
                if entry.duplicate { return Err("duplicate field `scripts`".to_string()); }
                // The seen check above for completeness; duplicate entries are flagged.
                seen.insert("scripts".to_string());
                cfg.scripts=to_scripts(&entry.node)?;
            }
            "default"=>{
                if entry.duplicate { return Err("duplicate field `default`".to_string()); }
                seen.insert("default".to_string());
                cfg.default=to_default(&entry.node)?;
            }
            _=>{}
        }
    }
    Ok(cfg)
}

// ---------- Serialization ----------
fn escape_basic(s:&str, multiline:bool)->String{
    let mut out=String::new();
    for c in s.chars(){
        match c {
            '\u{8}'=>out.push_str("\\b"),
            '\t'=>out.push_str("\\t"),
            '\n'=>{ if multiline{out.push('\n')}else{out.push_str("\\n")} }
            '\u{c}'=>out.push_str("\\f"),
            '\r'=>out.push_str("\\r"),
            '"'=>out.push_str("\\\""),
            '\\'=>out.push_str("\\\\"),
            c if (c as u32) <= 0x1e => { out.push_str(&format!("\\u{:04X}",c as u32)); }
            c=>out.push(c),
        }
    }
    out
}
fn must_basic(s:&str)->bool{
    s.contains("'''") || s.ends_with('\'') || s.chars().any(|c| (c as u32)<=0x1e && c!='\t' && c!='\n')
}
pub fn repr_string(s:&str)->String{
    if must_basic(s) {
        if s.contains('\n'){ format!("\"\"\"\n{}\"\"\"",escape_basic(s,true)) }
        else{ format!("\"{}\"",escape_basic(s,false)) }
    } else if s.contains('\n') {
        format!("'''\n{}'''",s)
    } else if s.contains('\'') {
        format!("'''{}'''",s)
    } else {
        format!("'{}'",s)
    }
}
fn repr_key(s:&str)->String{
    if s.chars().all(|c| c.is_ascii_alphanumeric() || c=='_' || c=='-') {
        s.to_string()
    } else {
        format!("\"{}\"",escape_basic(s,false))
    }
}
fn repr_array(vals:&[String])->String{
    if vals.is_empty(){ return "[]".to_string(); }
    if vals.len()==1{ return format!("[{}]",repr_string(&vals[0])); }
    let mut out="[\n".to_string();
    for v in vals{ out.push_str(&format!("    {},\n",repr_string(v))); }
    out.push(']');
    out
}
pub fn serialize_config(cfg:&Config)->String{
    let mut out=String::new();
    if cfg.scripts.is_empty() {
        out.push_str("[scripts]\n");
    } else {
        for (alias,script) in &cfg.scripts {
            if !out.is_empty(){ out.push('\n'); }
            out.push_str(&format!("[scripts.{}]\n",repr_key(alias)));
            out.push_str(&format!("command = {}\n",repr_string(&script.command)));
            if let Some(desc)=&script.description{ out.push_str(&format!("description = {}\n",repr_string(desc))); }
            if let Some(tags)=&script.tags{ out.push_str(&format!("tags = {}\n",repr_array(tags))); }
        }
    }
    if !out.is_empty(){ out.push('\n'); }
    out.push_str("[default]\n");
    if let Some(interp)=&cfg.default.interpreter{ out.push_str(&format!("interpreter = {}\n",repr_array(interp))); }
    if let Some(w)=cfg.default.command_width{ out.push_str(&format!("command_width = {}\n",w)); }
    out
}
