impl Parser {
    fn new(input:&str)->Self{ Self{chars:input.chars().collect(),pos:0,line:1,seq:0,root:TableData::new(String::new(),1,0),current_path:Vec::new()} }
    fn next_seq(&mut self)->u64{ self.seq+=1; self.seq }
    fn eof(&self)->bool{ self.pos>=self.chars.len() }
    fn peek(&self)->Option<char>{ self.chars.get(self.pos).copied() }
    fn peek_at(&self,off:usize)->Option<char>{ self.chars.get(self.pos+off).copied() }
    fn starts_with(&self,s:&str)->bool{
        let v:Vec<char>=s.chars().collect();
        if self.pos+v.len()>self.chars.len(){return false}
        self.chars[self.pos..self.pos+v.len()]==v[..]
    }
    fn advance(&mut self)->Option<char>{
        let c=self.peek()?;
        self.pos+=1;
        if c=='\n'{self.line+=1;}
