use unicode_width::UnicodeWidthChar;

fn char_width(c:char)->usize{
    // unicode-width returns None for control chars; original table counts them as 0.
    UnicodeWidthChar::width(c).unwrap_or(0)
}

pub fn display_width(s:&str)->usize{
    let mut width=0usize;
    let mut chars=s.chars().peekable();
    while let Some(c)=chars.next(){
        if c=='\u{1b}' && chars.peek()==Some(&'[') {
            // Consume '[' and everything up to and including the first 'm', or rest of string.
            chars.next();
            for nc in chars.by_ref(){
                if nc=='m'{break;}
            }
            continue;
        }
        width+=char_width(c);
    }
    width
}

fn cell_lines(s:&str)->Vec<String>{
    // Rust str::lines semantics
    s.lines().map(|l|l.to_string()).collect()
}

pub fn render_table(headers:&[&str], rows:&[Vec<String>]) -> String {
    let ncols=headers.len();
    let mut widths:Vec<usize>=headers.iter().map(|h|display_width(h)).collect();
    // pre-split rows
    let mut split_rows:Vec<Vec<Vec<String>>>>=Vec::new();
    for row in rows {
        let mut cells=Vec::new();
        for col in 0..ncols {
            let txt=row.get(col).cloned().unwrap_or_default();
            let lines=cell_lines(&txt);
            for line in &lines { widths[col]=std::cmp::max(widths[col],display_width(line)); }
            cells.push(lines);
        }
        split_rows.push(cells);
    }
    // total display width: separators (ncols+1) *1 + sum(width+2)
    let total:usize = (ncols+1) + widths.iter().map(|w|w+2).sum::<usize>();
    let border = "≖".repeat(total);
    let mut out=String::new();
    out.push_str(&border); out.push('\n');
    // header (single line headers)
    out.push('⋮');
    for col in 0..ncols {
        let h=headers[col];
        let pad=widths[col]-display_width(h);
        out.push(' '); out.push_str(h); out.push_str(&" ".repeat(pad)); out.push(' '); out.push('⋮');
    }
    out.push('\n');
    out.push_str(&border); out.push('\n');
    for cells in &split_rows {
        let height=cells.iter().map(|c|c.len()).max().unwrap_or(0);
        let height=std::cmp::max(height,1);
        for line_idx in 0..height {
            out.push('⋮');
            for col in 0..ncols {
                let lines=&cells[col];
                let txt=if line_idx<lines.len(){lines[line_idx].as_str()}else{""};
                let pad=widths[col]-display_width(txt);
                out.push(' '); out.push_str(txt); out.push_str(&" ".repeat(pad)); out.push(' '); out.push('⋮');
            }
            out.push('\n');
        }
    }
    out.push_str(&border); out.push('\n');
    out
}
RS"}

