{"command":"cat > src/main.rs <<'RS'
mod cli;
mod help;
mod table;
mod toml_cfg;
mod util;

use cli::*;
use std::collections::BTreeMap;
use std::ffi::OsString;
use std::fs::{self, File};
use std::io::{self, Write};
use std::os::unix::ffi::OsStrExt;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use toml_cfg::{Config, DefaultOpts, Script};
use util::*;

// ----- globals -----
struct Global {
    verbose: bool,
    config_file: Option<String>,
}

fn bin_name(argv0: Option<OsString>) -> String {
    let Some(a0) = argv0 else { return "pier".to_string() };
    let bytes = a0.as_os_str().as_bytes();
    let comp = match bytes.iter().rposition(|&b| b == b'/') {
        Some(idx) => &bytes[idx+1..],
        None => bytes,
    };
    if comp.is_empty() { return "pier".to_string(); }
    match std::str::from_utf8(comp) {
        Ok(s) if !s.is_empty() => s.to_string(),
        _ => "pier".to_string(),
    }
}

fn main() {
    let mut args_os = std::env::args_os();
    let argv0 = args_os.next();
    let bin = bin_name(argv0);
    let tokens: Vec<Bytes> = args_os.map(|a| a.as_os_str().as_bytes().to_vec()).collect();
    let env_config_display = std::env::var_os("PIER_CONFIG_PATH").map(|v| lossy(v.as_os_str().as_bytes())).unwrap_or_default();
    let ctx = Ctx { bin, env_config_display };
    match run_app(&ctx, &tokens) {
        Ok(()) => {}
        Err(msg) => {
            eprintln!("error: {}", msg);
            std::process::exit(1);
        }
    }
}

fn insert_env_config(parsed: &mut Parsed) {
    if parsed.occ("config-file") == 0 {
        if let Some(v) = std::env::var_os("PIER_CONFIG_PATH") {
            parsed.add_occurrence("config-file");
            parsed.add_value("config-file", v.as_os_str().as_bytes().to_vec());
        }
    }
}

fn run_app(ctx: &Ctx, tokens:&[Bytes]) -> Result<(),String> {
    let outcome = parse_top(ctx, tokens);
    let mut top_parsed = outcome.top_parsed;
    match outcome.kind {
        TopOutcomeKind::HelpTopic(topics) => {
            handle_help_topic(ctx, &topics);
        }
        TopOutcomeKind::Subcommand(canon, subparsed) => {
            let subspec = spec_for(&canon);
            validate_parsed(ctx,&subspec,&subparsed,false);
            insert_env_config(&mut top_parsed);
            let topspec = top_spec();
            validate_parsed(ctx,&topspec,&top_parsed,false);
            let global = extract_global(&top_parsed);
            // top alias/args extraction for invalid-UTF8 behaviour before subcommand execution
            let _top_alias = top_parsed.first("alias").map(|b| utf8_single(&b));
            let _top_args = utf8_values(&top_parsed.vals("args"));
            dispatch_subcommand(ctx,&global,&canon,&subparsed)
        }
        TopOutcomeKind::AliasRun => {
            insert_env_config(&mut top_parsed);
            let topspec = top_spec();
            validate_parsed(ctx,&topspec,&top_parsed,true);
            let global = extract_global(&top_parsed);
            let alias = utf8_single(&top_parsed.first("alias").unwrap_or_default());
            let args = utf8_values(&top_parsed.vals("args"));
            let (cfg,_path) = load_config(&global)?;
            run_script(&cfg,&alias,&args,global.verbose)
        }
    }
}

fn extract_global(top_parsed:&Parsed)->Global{
    // config-file single conversion first
    let config_file = top_parsed.first("config-file").map(|b| utf8_single(&b));
    Global{verbose: top_parsed.occ("verbose")>0, config_file}
}

fn single_val(parsed:&Parsed,id:&str)->Option<String>{ parsed.first(id).map(|b|utf8_single(&b)) }
fn req_single(parsed:&Parsed,id:&str)->String{ single_val(parsed,id).unwrap_or_default() }

fn dispatch_subcommand(ctx:&Ctx, global:&Global, canon:&str, parsed:&Parsed)->Result<(),String>{
    match canon {
        "list" => {
            let cmd_full=parsed.occ("cmd_full")>0;
            let list_aliases=parsed.occ("list_aliases")>0;
            let cmd_width:Option<usize>=parsed.first("cmd_width").map(|b| lossy(&b).parse::<usize>().unwrap());
            let tags:Option<Vec<String>>=if parsed.occ("tags")>0{Some(utf8_values(&parsed.vals("tags")))}else{None};
            do_list(global,cmd_full,list_aliases,cmd_width,tags)
        }
        "show" => {
            let alias=req_single(parsed,"alias");
            let (cfg,_)=load_config(global)?;
            let script=cfg.scripts.get(&alias).ok_or_else(||format!("AliasNotFound: No script found by alias {}",alias))?;
            println!("{}",script.command);
            Ok(())
        }
        "run" => {
            let alias=req_single(parsed,"alias");
            let args=utf8_values(&parsed.vals("args"));
            let (cfg,_)=load_config(global)?;
            run_script(&cfg,&alias,&args,global.verbose)
        }
        "add" => {
            // singles first
            let alias=req_single(parsed,"alias");
            let description=single_val(parsed,"description");
            let command=single_val(parsed,"command");
            let tags:Option<Vec<String>>=if parsed.occ("tags")>0{Some(utf8_values(&parsed.vals("tags")))}else{None};
            let force=parsed.occ("force")>0;
            do_add(global,alias,description,tags,command,force)
        }
        "remove" => {
            let alias=req_single(parsed,"alias");
            let (mut cfg,path)=load_config(global)?;
            if !cfg.scripts.contains_key(&alias){ return Err(format!("AliasNotFound: No script found by alias {}",alias)); }
            cfg.scripts.remove(&alias);
            println!("Removed {}",alias);
            write_config(&path,&cfg)
        }
        "copy" => {
            let from=req_single(parsed,"from-alias");
            let to=req_single(parsed,"to-alias");
            let (mut cfg,path)=load_config(global)?;
            if cfg.scripts.contains_key(&to){ return Err(format!("AliasAlreadyExists:  {}",to)); }
            let script=cfg.scripts.get(&from).cloned().ok_or_else(||format!("AliasNotFound: No script found by alias {}",from))?;
            cfg.scripts.insert(to.clone(),script);
            println!("Copy from alias {} to new alias {}",from,to);
            write_config(&path,&cfg)
        }
        "move" => {
            let from=req_single(parsed,"from-alias");
            let to=req_single(parsed,"to-alias");
            let force=parsed.occ("force")>0;
            let (mut cfg,path)=load_config(global)?;
            if cfg.scripts.contains_key(&to) && !force { return Err(format!("AliasAlreadyExists:  {}",to)); }
            let script=cfg.scripts.remove(&from).ok_or_else(||format!("AliasNotFound: No script found by alias {}",from))?;
            cfg.scripts.insert(to.clone(),script);
            println!("Move from alias {} to new alias {}",from,to);
            write_config(&path,&cfg)
        }
        "edit" => {
            let alias=req_single(parsed,"alias");
            do_edit(global,alias)
        }
        "config-init" => {
            do_config_init(global)
        }
        _=> unreachable!(),
    }
}

// ----- config paths -----
fn uid_from_proc()->Option<u32>{
    let content=fs::read_to_string("/proc/self/status").ok()?;
    for line in content.lines(){
        if let Some(rest)=line.strip_prefix("Uid:"){
            let first=rest.split_whitespace().next()?;
            return first.parse::<u32>().ok();
        }
    }
    None
}
fn home_dir()->Option<PathBuf>{
    if let Some(v)=std::env::var_os("HOME") {
        if !v.is_empty(){ return Some(PathBuf::from(v)); }
    }
    // passwd fallback using uid
    let uid=uid_from_proc()?;
    let data=fs::read("/etc/passwd").ok()?;
    for line in data.split(|&b|b==b'\n') {
        let fields:Vec<&[u8]>=line.split(|&b|b==b':').collect();
        if fields.len()>=6 {
            if let Ok(u)=std::str::from_utf8(fields[2]).unwrap_or("").parse::<u32>() {
                if u==uid && !fields[5].is_empty() {
                    return Some(PathBuf::from(std::ffi::OsString::from_vec(fields[5].to_vec())));
                }
            }
        }
    }
    None
}
// need OsStringExt for from_vec
use std::os::unix::ffi::OsStringExt;

fn config_dir()->Option<PathBuf>{
    if let Some(v)=std::env::var_os("XDG_CONFIG_HOME") {
        let p=PathBuf::from(v);
        if p.is_absolute(){ return Some(p); }
    }
    home_dir().map(|h|h.join(".config"))
}
fn existing_candidates()->Vec<PathBuf>{
    let mut v=vec![PathBuf::from("pier.toml")];
    if let Some(cd)=config_dir(){
        v.push(cd.join("pier/config.toml"));
        v.push(cd.join("pier/config"));
        v.push(cd.join("pier.toml"));
    }
    if let Some(h)=home_dir(){
        v.push(h.join(".pier.toml"));
        v.push(h.join(".pier"));
    }
    v
}
fn find_existing_config()->Option<PathBuf>{
    existing_candidates().into_iter().find(|p|p.exists())
}
fn resolve_config_path(global:&Global)->Result<PathBuf,String>{
    if let Some(p)=&global.config_file{ return Ok(PathBuf::from(p)); }
    find_existing_config().ok_or_else(||"No default config file found. See help for more info.".to_string())
}
fn resolve_init_path(global:&Global)->PathBuf{
    if let Some(p)=&global.config_file{ return PathBuf::from(p); }
    if let Some(f)=find_existing_config(){ return f; }
    if let Some(cd)=config_dir(){ return cd.join("pier/config.toml"); }
    PathBuf::from("pier/config.toml")
}
fn load_config(global:&Global)->Result<(Config,PathBuf),String>{
    let path=resolve_config_path(global)?;
    let content=fs::read_to_string(&path).map_err(|e|format!("Unable to read config from file {}: {} ",path.display(),e))?;
    let cfg=toml_cfg::parse_config(&content).map_err(|e|format!("Unable to parse toml config from file {}: {}",path.display(),e))?;
    Ok((cfg,path))
}
fn write_config(path:&PathBuf,cfg:&Config)->Result<(),String>{
    let text=toml_cfg::serialize_config(cfg);
    fs::write(path,text).map_err(|e|format!("Unable to write config to {}: {}",path.display(),e))
}

// ----- commands -----
fn do_list(global:&Global,cmd_full:bool,list_aliases:bool,cmd_width:Option<usize>,tags:Option<Vec<String>>)->Result<(),String>{
    let (cfg,_)=load_config(global)?;
    if cfg.scripts.is_empty(){ return Err("No scripts exist. Would you like to add a new script?".to_string()); }
    // filtered in BTree order
    let mut filtered:Vec<(&String,&Script)>=Vec::new();
    if let Some(filter_tags)=tags {
        for (alias,script) in &cfg.scripts {
            for ft in &filter_tags {
                if let Some(st)=&script.tags {
                    if st.contains(ft){ filtered.push((alias,script)); }
                }
            }
        }
    } else {
        for (a,s) in &cfg.scripts{filtered.push((a,s));}
    }
    if list_aliases {
        for (alias,_) in &filtered{ println!("{}",alias); }
        return Ok(());
    }
    let width_opt = if cmd_full {None} else {Some(cmd_width.or(cfg.default.command_width).unwrap_or(80))};
    let mut rows:Vec<Vec<String>>=Vec::new();
    for (alias,script) in &filtered {
        let cmd_disp=if let Some(w)=width_opt { trunc_command(&script.command,w).to_string() } else { script.command.clone() };
        let tag_disp=script.tags.as_ref().map(|t|t.join(",")).unwrap_or_default();
        let desc=script.description.clone().unwrap_or_default();
        rows.push(vec![alias.to_string(),tag_disp,cmd_disp,desc]);
    }
    let text=table::render_table(&["Alias","Tags","Command","Description"],&rows);
    let _=io::stdout().write_all(text.as_bytes());
    let _=io::stdout().flush();
    Ok(())
}

fn trunc_command(cmd:&str,width:usize)->&str{
    let first=cmd.lines().next().unwrap_or("");
    if first.chars().count()>width {
        if !first.is_char_boundary(width){
            // find char containing byte width
            let mut start=0usize; let mut end=0usize; let mut ch='?';
            for (i,c) in first.char_indices(){
                if width>=i && width < i+c.len_utf8(){ start=i; end=i+c.len_utf8(); ch=c; break; }
            }
            panic_fake("src/script.rs:36:52",&format!("byte index {} is not a char boundary; it is inside '{}' (bytes {}..{}) of `{}`",width,ch,start,end,first));
        }
        &first[..width]
    } else { first }
}

fn do_add(global:&Global,alias:String,description:Option<String>,tags:Option<Vec<String>>,command:Option<String>,force:bool)->Result<(),String>{
    let (mut cfg,path)=load_config(global)?;
    let command_str=match command{ Some(c)=>c, None=>editor_input("")? };
    if cfg.scripts.contains_key(&alias) && !force {
        return Err(format!("AliasAlreadyExists:  {}",alias));
    }
    cfg.scripts.insert(alias.clone(),Script{command:command_str,description,tags});
    println!("Added {}",alias);
    write_config(&path,&cfg)
}

fn do_edit(global:&Global,alias:String)->Result<(),String>{
    let (mut cfg,path)=load_config(global)?;
    let old=cfg.scripts.get(&alias).ok_or_else(||format!("AliasNotFound: No script found by alias {}",alias))?.command.clone();
    let new_cmd=editor_input(&old)?;
    if let Some(s)=cfg.scripts.get_mut(&alias){ s.command=new_cmd; }
    println!("Edited {}",alias);
    write_config(&path,&cfg)
}

fn do_config_init(global:&Global)->Result<(),String>{
    let path=resolve_init_path(global);
    if path.exists(){
        return Err(format!("Cannot initialize config at {}, file already exists.",path.display()));
    }
    if let Some(parent)=path.parent(){
        if !parent.exists(){
            fs::create_dir(parent).map_err(|e|format!("Failed to create directory. {}",e))?;
        }
    }
    let mut cfg=Config::default();
    cfg.scripts.insert("hello-pier".to_string(),Script{command:"echo Hello, Pier!".to_string(),description:Some("This is an example command.".to_string()),tags:None});
    println!("Added hello-pier");
    write_config(&path,&cfg)
}

fn run_script(cfg:&Config,alias:&str,args:&[String],verbose:bool)->Result<(),String>{
    let script=cfg.scripts.get(alias).ok_or_else(||format!("AliasNotFound: No script found by alias {}",alias))?;
    if verbose{
        println!("Starting script \"{}\"",alias);
        println!("{}", "-".repeat(25));
    }
    let interpreter:Vec<String>=if let Some(v)=&cfg.default.interpreter{ v.clone() } else { vec![std::env::var("SHELL").unwrap_or_else(|_|"/bin/sh".to_string()),"-c".to_string()] };
    if interpreter.is_empty(){
        panic_fake("src/script.rs:52:44","index out of bounds: the len is 0 but the index is 0");
    }
    let output_res=Command::new(&interpreter[0]).args(&interpreter[1..]).arg(&script.command).arg(alias).args(args).stdin(Stdio::inherit()).output();
    let output=match output_res{ Ok(o)=>o, Err(e)=>return Err(format!("Command execution failed with: {}",e)) };
    let _=io::stdout().write_all(&output.stdout);
    let _=io::stdout().flush();
    if !output.stderr.is_empty(){
        eprintln!("{}",String::from_utf8_lossy(&output.stderr));
    }
    if verbose{
        println!("{}", "-".repeat(25));
        println!("Script complete");
    }
    std::process::exit(output.status.code().unwrap_or(0));
}

// ----- editor (scrawl emulation) -----
fn editor_input(initial:&str)->Result<String,String>{
    let err_prefix="EditorError: Failed when trying to get input from editor ";
    let temp_dir=std::env::var_os("TMPDIR").map(PathBuf::from).unwrap_or_else(||PathBuf::from("/tmp"));
    let path=temp_dir.join(format!("xvrqt_scrawl_{}_0",std::process::id()));
    {
        let mut file=File::create(&path).map_err(|_|format!("{}Could not create a temporary file to serve as a buffer for the editor.",err_prefix))?;
        if file.write_all(initial.as_bytes()).and_then(|_|file.flush()).is_err(){
            return Err(format!("{}Failed to copy the contents of the `[String]` to the buffer for editing.",err_prefix));
        }
    }
    let editor=std::env::var("VISUAL").or_else(|_|std::env::var("EDITOR")).unwrap_or_else(|_|"vi".to_string());
    let status_res=Command::new(&editor).arg(&path).status();
    let ok=match status_res{ Ok(s)=>s.success(), Err(_)=>false };
    if !ok{
        return Err(format!("{}Failed to open `{}` as a text editor or editor was terminated with errors.",err_prefix,editor));
    }
    fs::read_to_string(&path).map_err(|_|format!("{}Failed to capture input. Was not a valid UTF-8 String.",err_prefix))
}
RS"}

