    if verbose{
        println!("Starting script \"{}\"",alias);
        println!("{}", "-".repeat(25));
    }
    let interpreter:Vec<String>=if let Some(v)=&cfg.default.interpreter{ v.clone() } else { vec![std::env::var("SHELL").unwrap_or_else(|_|"/bin/sh".to_string()),"-c".to_string()] };
