    let first=cmd.lines().next().unwrap_or("");
    if first.chars().count()>width {
        if !first.is_char_boundary(width){
            // find char containing byte width
            let mut start=0usize; let mut end=0usize; let mut ch='?';
            for (i,c) in first.char_indices(){
                if width>=i && width < i+c.len_utf8(){ start=i; end=i+c.len_utf8(); ch=c; break; }
            }
            panic_fake("src/script.rs:36:52",&format!("byte index {} is not a char boundary; it is inside '{}' (bytes {}..{}) of `{}`",width,ch,start,end,first));
        }
        &first[..width]
    } else { first }
}

fn do_add(global:&Global,alias:String,description:Option<String>,tags:Option<Vec<String>>,command:Option<String>,force:bool)->Result<(),String>{
    let (mut cfg,path)=load_config(global)?;
    let command_str=match command{ Some(c)=>c, None=>editor_input("")? };
    if cfg.scripts.contains_key(&alias) && !force {
        return Err(format!("AliasAlreadyExists:  {}",alias));
    }
    cfg.scripts.insert(alias.clone(),Script{command:command_str,description,tags});
    println!("Added {}",alias);
    write_config(&path,&cfg)
}

fn do_edit(global:&Global,alias:String)->Result<(),String>{
    let (mut cfg,path)=load_config(global)?;
    let old=cfg.scripts.get(&alias).ok_or_else(||format!("AliasNotFound: No script found by alias {}",alias))?.command.clone();
    let new_cmd=editor_input(&old)?;
    if let Some(s)=cfg.scripts.get_mut(&alias){ s.command=new_cmd; }
    println!("Edited {}",alias);
    write_config(&path,&cfg)
}

fn do_config_init(global:&Global)->Result<(),String>{
    let path=resolve_init_path(global);
    if path.exists(){
        return Err(format!("Cannot initialize config at {}, file already exists.",path.display()));
    }
    if let Some(parent)=path.parent(){
        if !parent.exists(){
            fs::create_dir(parent).map_err(|e|format!("Failed to create directory. {}",e))?;
        }
    }
    let mut cfg=Config::default();
    cfg.scripts.insert("hello-pier".to_string(),Script{command:"echo Hello, Pier!".to_string(),description:Some("This is an example command.".to_string()),tags:None});
    println!("Added hello-pier");
    write_config(&path,&cfg)
}

fn run_script(cfg:&Config,alias:&str,args:&[String],verbose:bool)->Result<(),String>{
    let script=cfg.scripts.get(alias).ok_or_else(||format!("AliasNotFound: No script found by alias {}",alias))?;
    if verbose{
        println!("Starting script \"{}\"",alias);
        println!("{}", "-".repeat(25));
    }
    let interpreter:Vec<String>=if let Some(v)=&cfg.default.interpreter{ v.clone() } else { vec![std::env::var("SHELL").unwrap_or_else(|_|"/bin/sh".to_string()),"-c".to_string()] };
    if interpreter.is_empty(){
        panic_fake("src/script.rs:52:44","index out of bounds: the len is 0 but the index is 0");
    }
    let output_res=Command::new(&interpreter[0]).args(&interpreter[1..]).arg(&script.command).arg(alias).args(args).stdin(Stdio::inherit()).output();
    let output=match output_res{ Ok(o)=>o, Err(e)=>return Err(format!("Command execution failed with: {}",e)) };
    let _=io::stdout().write_all(&output.stdout);
    let _=io::stdout().flush();
    if !output.stderr.is_empty(){
        eprintln!("{}",String::from_utf8_lossy(&output.stderr));
    }
    if verbose{
        println!("{}", "-".repeat(25));
        println!("Script complete");
    }
    std::process::exit(output.status.code().unwrap_or(0));
}

// ----- editor (scrawl emulation) -----
fn editor_input(initial:&str)->Result<String,String>{
    let err_prefix="EditorError: Failed when trying to get input from editor ";
    let temp_dir=std::env::var_os("TMPDIR").map(PathBuf::from).unwrap_or_else(||PathBuf::from("/tmp"));
    let path=temp_dir.join(format!("xvrqt_scrawl_{}_0",std::process::id()));
    {
        let mut file=File::create(&path).map_err(|_|format!("{}Could not create a temporary file to serve as a buffer for the editor.",err_prefix))?;
        if file.write_all(initial.as_bytes()).and_then(|_|file.flush()).is_err(){
            return Err(format!("{}Failed to copy the contents of the `[String]` to the buffer for editing.",err_prefix));
        }
    }
    let editor=std::env::var("VISUAL").or_else(|_|std::env::var("EDITOR")).unwrap_or_else(|_|"vi".to_string());
    let status_res=Command::new(&editor).arg(&path).status();
    let ok=match status_res{ Ok(s)=>s.success(), Err(_)=>false };
    if !ok{
        return Err(format!("{}Failed to open `{}` as a text editor or editor was terminated with errors.",err_prefix,editor));
    }
    fs::read_to_string(&path).map_err(|_|format!("{}Failed to capture input. Was not a valid UTF-8 String.",err_prefix))
}
