import subprocess,os,pathlib,shutil
chars=[]
for cp in range(0x20,0x10000):
    if 0xD800<=cp<=0xDFFF: continue
    if cp<0xa0 and cp!=0x20: continue
    if cp in (0x22EE,0x2256): continue
    chars.append(cp)

def widths(exe,cps):
    d="/tmp/widthscan"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d+"/.config/pier")
    txt=""
    for i,cp in enumerate(cps):
        txt+=f"[scripts.s{i:05d}]\ncommand=\"\\u{cp:04x}\"\n"
    pathlib.Path(d+"/.config/pier/config.toml").write_text(txt)
    env={"PATH":os.environ["PATH"],"HOME":d,"XDG_CONFIG_HOME":d+"/.config"}
    r=subprocess.run([exe,"list"],cwd=d,env=env,capture_output=True,text=True)
    if r.returncode!=0:
        return None, r.stderr
    vals={}
    for line in r.stdout.split("\n"):
        if "⋮ s" in line:
            parts=line.split("⋮")
            if len(parts)<5: continue
            alias=parts[1].strip()
            try: idx=int(alias[1:])
            except: continue
            seg=parts[3]
            trailing=len(seg)-len(seg.rstrip(' '))
            width=8-trailing
            vals[idx]=width
    return vals,None

batch=250
diffs=[]
for start in range(0,len(chars),batch):
    cps=chars[start:start+batch]
    old,err=widths("/workspace/executable",cps)
