    if old is None or new is None:
        print("ERR batch",start,err,err2); continue
    if len(old)!=len(cps) or len(new)!=len(cps):
        # may be multi-line / separator chars; report missing only
        pass
    for i,cp in enumerate(cps):
        if i in old and i in new and old[i]!=new[i]:
            diffs.append((cp,old[i],new[i]))
    if start%5000==0: print(start,"diffs",len(diffs))
print("total diffs",len(diffs))
for cp,o,n in diffs[:500]:
    print(f"U+{cp:04X} old={o} new={n} char={chr(cp)!r}")
pathlib.Path("/tmp/widthdiffs.txt").write_text("\n".join(f"{cp:04X} {o} {n}" for cp,o,n in diffs))
PY
